using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Security;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Modules;[Authorize(Policy="SuperAdminOnly")]public sealed class EditModel(OrcaFacilDbContext db):PageModel{[BindProperty]public ModuleInput Input{get;set;}=new();[BindProperty]public bool Active{get;set;}public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){var x=await db.SaasModules.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&!x.IsDeleted,ct);if(x is null)return NotFound();Input=new(){Id=x.Id,Code=x.Code,DisplayName=x.DisplayName,Category=x.Category,MenuGroup=x.MenuGroup,RoutePrefix=x.RoutePrefix,Permission=x.RequiredPermissionCode,MonthlyPrice=x.BaseMonthlyPrice,AnnualPrice=x.BaseAnnualPrice};Active=x.IsActive;return Page();}public async Task<IActionResult>OnPostAsync(CancellationToken ct){if(!PermissionCodes.All.Contains(Input.Permission))ModelState.AddModelError("Input.Permission","Use uma permissão registrada no backend.");if(!ModelState.IsValid)return Page();var x=await db.SaasModules.SingleOrDefaultAsync(x=>x.Id==Input.Id&&!x.IsDeleted,ct);if(x is null)return NotFound();x.DisplayName=Input.DisplayName;x.Category=Input.Category;x.MenuGroup=Input.MenuGroup;x.RoutePrefix=Input.RoutePrefix;x.RequiredPermissionCode=Input.Permission;x.BaseMonthlyPrice=Input.MonthlyPrice;x.BaseAnnualPrice=Input.AnnualPrice;x.IsActive=Active;x.Touch();db.AccountModuleAuditLogs.Add(new(){ActorUserId=Guid.TryParse(User.FindFirstValue("user_id"),out var a)?a:Guid.Empty,Action="GlobalModuleUpdated",EntityType=nameof(SaasModule),EntityId=x.Id.ToString(),ModuleCode=x.Code,Summary="Configuração ou preço do módulo alterado.",CorrelationId=HttpContext.TraceIdentifier});await db.SaveChangesAsync(ct);return RedirectToPage(new{id=x.Id});}}
